create role anon; create role authenticated; create role service_role;
create schema private;
create table public.collector_cloud_listing_scans(id uuid, source_id uuid, row_count int check (row_count between 1 and 400));
create table public.collector_cloud_listing_rows(ordinal int check (ordinal >= 0 and ordinal < 100), canonical_url text check (canonical_url ~ '^https://www[.]ftc[.]gov/' and octet_length(canonical_url)<=2048), row_data jsonb check (octet_length(row_data::text)<=5000), url_hash text, scan_id uuid, source_id uuid);
create function public.collector_web_ingest(body text, metadata jsonb, title text) returns boolean language plpgsql as $$ begin if octet_length(body) not between 100 and 400000 or length(title) not between 1 and 1000 then return false; end if; return true; end $$;
create function private.collector_cloud_frozen_cursor_valid(c jsonb, slug text) returns boolean language plpgsql immutable set search_path=pg_catalog as $$ declare u jsonb; path_pattern text; listing_pattern text; count_urls integer; begin if not (c ? 'frozen_urls') then return not (c ? 'frozen_next'); end if; if slug not in ('ec','eu-parliament') or jsonb_typeof(c->'frozen_urls') is distinct from 'array' then return false; end if; count_urls=jsonb_array_length(c->'frozen_urls'); if count_urls not between 1 and 100 or octet_length(c::text)>4000 or not (c ? 'frozen_next') then return false; end if; if jsonb_typeof(c->'offset') is distinct from 'number' or (c->>'offset') !~ '^[0-9]{1,6}$' or (c->>'offset')::integer>count_urls then return false; end if; if slug='ec' then path_pattern='^https://ec[.]europa[.]eu/commission/presscorner/detail/en/(ip|qanda|statement|speech|memo|mex)_[0-9]{2}_[0-9]+$'; listing_pattern='^https://ec[.]europa[.]eu/commission/presscorner/api/search[?][^#]+$'; else path_pattern='^https://www[.]europarl[.]europa[.]eu/news/en/press-room/[0-9]{8}IPR[0-9]+/[^?#]*$'; listing_pattern='^https://www[.]europarl[.]europa[.]eu/rss/doc/press-releases/en[.]xml$'; end if; if c->>'page' !~ listing_pattern then return false; end if; if jsonb_typeof(c->'frozen_next') not in ('null','string') then return false; end if; if c->'frozen_next'<>'null'::jsonb and (slug='eu-parliament' or c->>'frozen_next' !~ listing_pattern) then return false; end if; for u in select value from jsonb_array_elements(c->'frozen_urls') loop if jsonb_typeof(u) is distinct from 'string' or u#>>'{}' !~ path_pattern or octet_length(u#>>'{}')>2048 then return false; end if; end loop; if (select count(distinct value) from jsonb_array_elements(c->'frozen_urls'))<>count_urls then return false; end if; return true; end $$;
create function private.collector_cloud_cursor_valid(c jsonb, slug text) returns boolean language plpgsql immutable as $$ declare field text; begin if octet_length(c::text)>4000 then return false; end if; if (c->>'offset') !~ '^[0-9]{1,6}$' then return false; end if; foreach field in array array['offset','page'] loop if (c->>field) !~ '^[0-9]{1,9}$' then return false; end if; end loop; if jsonb_array_length(c->'processed_url_hashes')>50 then return false; end if; return true; end $$;
create function public.collector_set_progress(p_id uuid,p_since date,p_until date,p_cursor jsonb,p_done boolean) returns boolean language plpgsql as $$ begin if octet_length(coalesce(p_cursor::text,''))>4000 then return false; end if; return true; end $$;
create function public.collector_cloud_commit(p_id uuid,p_worker text,p_item uuid,p_bundle jsonb,p_hash text) returns boolean language plpgsql as $$ declare listing jsonb; x jsonb; begin if octet_length(p_bundle::text)>500000 then return false; end if; if jsonb_array_length(listing->'rows') not between 1 and 100 then return false; end if; if octet_length(x->>'url')>2048 or octet_length(x->>'title')>1000 then return false; end if; if jsonb_array_length(coalesce(x->'date_observations','[]'::jsonb))>4 or octet_length(x::text)>5000 then return false; end if; return true; end $$;
create function public.collector_cloud_take(p_worker text,p_slug text) returns jsonb language plpgsql as $$ declare snapshot_hashes jsonb; previous_hashes jsonb; r record; staged_row record; s record; scan record; p_source_id uuid; begin if p_slug in ('oecd','ftc') then null; end if; select coalesce(jsonb_agg(lr.url_hash order by lr.ordinal),'[]'::jsonb) into snapshot_hashes from public.collector_cloud_listing_rows lr where lr.scan_id=scan.id and lr.source_id=p_source_id; perform jsonb_build_object('row',staged_row.row_data,'url_hashes',snapshot_hashes); select coalesce(jsonb_agg(h order by h),'[]'::jsonb) into previous_hashes from (select 'hash'::text h) seen; return null; end $$;
\i /app/supabase/migrations/20261108163000_remove_collector_throughput_ceilings.sql
do $test$ begin if private.collector_cloud_frozen_cursor_valid(jsonb_build_object('frozen_urls',jsonb_build_array('https://ec.europa.eu/commission/presscorner/detail/en/ip_26_123'),'frozen_next',null,'offset',repeat('9',1000)::numeric,'page','https://ec.europa.eu/commission/presscorner/api/search?language=en'),'ec') is distinct from false then raise exception 'huge numeric offset must return invalid, not throw'; end if; end $test$;
do $test$ begin if private.collector_cloud_frozen_cursor_valid(jsonb_build_object('frozen_urls',jsonb_build_array('https://ec.europa.eu/commission/presscorner/detail/en/ip_26_123'),'frozen_next',null,'offset',1,'page','https://ec.europa.eu/commission/presscorner/api/search?language=en'),'ec') is distinct from true then raise exception 'valid small offset must remain accepted'; end if; end $test$;



